// A3.1 read-only end-tick diagnostics. Never participates in steering/physics.
import {GR86} from './vehicle-spec.js';
export const traceColumns=['t_sim_s','car_t_s','touch_fraction','raw_demand','shaped_target','command','rack_deg','W0_deg','W1_deg','speed_kmh','yaw_rad_s','handler_age_ms','source_code','pad_active','pad_event_timestamp_ms','pad_received_ms','observed_event_code','observed_received_ms','gas_demand','filtered_throttle','clutch_torque_Nm','clutch_engagement','engine_omega','gear','net_drive_torque_Nm','negative_drive_torque_Nm','beta_rad','betaDot_filtered_rad_s','yawAccel_filtered_rad_s2','local_U','local_V','valid','reasons','damage','body_contacts','front_My_approx','rear_My_approx',...Array.from({length:4},(_,i)=>['alpha_geom_rad','alpha_relaxed_rad','kappa','Fx_N','Fy_N','Fz_N','force_limit_N','qratio','drive_torque_Nm','wheel_angle_rad','contact'].map(x=>'W'+i+'_'+x)).flat(),'digital_held','tilt_enabled','observed_event_source'];
export const observedEvents=Object.freeze({pointerdown:1,pointermove:2,pointerup:3,pointercancel:4,lostpointercapture:5,touchstart:6,touchmove:7,touchend:8,touchcancel:9,keydown:10,keyup:11,blur:12});
export class SteeringTrace{
 constructor(){this.capacity=1200;this.data=new Float64Array(this.capacity*traceColumns.length);this.count=0;this.cursor=0;this.clock=0;this.pending=0;this.enabled=true;this.eventCode=0;this.eventReceived=NaN;this.eventSource=0;this.digitalHeld=false;this.tiltEnabled=false;}
 attachInputs(pad,windowTarget,digitalButtons=[]){const observe=source=>e=>{this.eventCode=observedEvents[e.type]||0;this.eventReceived=performance.now();this.eventSource=source;};const padObserver=observe(1),buttonObserver=observe(2),keyObserver=observe(3);for(const name of ['pointerdown','pointermove','pointerup','pointercancel','lostpointercapture','touchstart','touchmove','touchend','touchcancel'])pad.addEventListener(name,padObserver,{passive:true});for(const element of digitalButtons)for(const name of ['pointerdown','pointerup','pointercancel','lostpointercapture'])element.addEventListener(name,buttonObserver,{passive:true});for(const name of ['keydown','keyup','blur'])windowTarget.addEventListener(name,keyObserver,{passive:true});}
 capture(v,c,pad,now,dt,state=null,input=null){
  if(!this.enabled)return;this.clock+=dt;this.pending+=dt;if(this.pending+1e-10<1/60)return;this.pending=0;
  const k=this.cursor*traceColumns.length,d=this.data,deg=180/Math.PI;
  d[k]=this.clock;d[k+1]=v.time;d[k+2]=pad?.fraction??NaN;d[k+3]=c.raw;d[k+4]=c.target;d[k+5]=c.position;d[k+6]=v.steer*deg;d[k+7]=v.wheels[0].steerAngle*deg;d[k+8]=v.wheels[1].steerAngle*deg;d[k+9]=v.speed*3.6;d[k+10]=v.yawRate;d[k+11]=Number.isFinite(pad?.receivedTime)?Math.max(0,now-pad.receivedTime):NaN;
  d[k+12]=c.mode==='touch'?1:c.mode==='digital'?2:3;d[k+13]=pad?.active?1:0;d[k+14]=pad?.eventTime??NaN;d[k+15]=pad?.receivedTime??NaN;d[k+16]=this.eventCode;d[k+17]=this.eventReceived;d[k+18]=input?.gas??NaN;d[k+19]=v.throttle;d[k+20]=v.clutchTorque;d[k+21]=v.clutchEngagement;d[k+22]=v.engineOmega;d[k+23]=v.gear;
  let drive=0,negative=0;for(const w of v.wheels){drive+=w.driveTorque;negative+=Math.min(0,w.driveTorque);}d[k+24]=drive;d[k+25]=negative;d[k+26]=state?.beta??NaN;d[k+27]=state?.betaDot??NaN;d[k+28]=state?.rDot??NaN;d[k+29]=state?.U??NaN;d[k+30]=state?.V??NaN;d[k+31]=state?.valid?1:0;d[k+32]=state?.reasons??NaN;d[k+33]=v.damage;d[k+34]=v.bodyContactCount;d[k+35]=state?.frontMoment??NaN;d[k+36]=state?.rearMoment??NaN;
  for(let i=0;i<4;i++){const w=v.wheels[i],o=state?.wheels[i],j=k+37+i*11,rest=GR86.mass*9.81*(w.front?GR86.frontWeight:1-GR86.frontWeight)/2,scale=Math.pow(Math.max(.08,Math.min(3.5,w.load/rest)),.8),q=Math.hypot(rest*23*scale*w.slip,(w.front?46000:60000)*scale*Math.tan(Math.max(-1.3,Math.min(1.3,w.alpha))));d[j]=o?.alphaGeom??NaN;d[j+1]=w.alpha;d[j+2]=w.slip;d[j+3]=w.fx;d[j+4]=w.fy;d[j+5]=w.load;d[j+6]=w.forceLimit;d[j+7]=w.contact&&w.load>100?q/(3*Math.max(w.forceLimit,1)):NaN;d[j+8]=w.driveTorque;d[j+9]=w.steerAngle;d[j+10]=w.contact?1:0;}
  d[k+81]=this.digitalHeld?1:0;d[k+82]=this.tiltEnabled?1:0;d[k+83]=this.eventSource;
  this.cursor=(this.cursor+1)%this.capacity;this.count=Math.min(this.count+1,this.capacity);
 }
 exportCSV(){const lines=['# '+JSON.stringify({version:'0.14A.3.1',format:'DrivingLabSteeringTrace/2',sampleHz:60,capacitySeconds:20,columns:traceColumns.length,observedEvents,notes:'End-tick forces/geometry, not exact substep force timing. Filtered derivatives existing40ms. Sim-time excludes pauses; car_t identifies resets. Event timestamps last values, NOT hardware touch/display latency. Observed pad/keyboard events may be ignored by control ownership; accepted pad timestamps separate. Source2 can mean released neutral touch, not digital button action. qratio>=1 combined brush saturation, NOT proof Fy is at lateral-only peak. Negative drive torque includes transmission/inertia/LSD, not isolated engine braking. Pause preserves buffer; no active assistance.'}),traceColumns.join(',')];const start=(this.cursor-this.count+this.capacity)%this.capacity;for(let i=0;i<this.count;i++){const k=(start+i)%this.capacity*traceColumns.length;lines.push(Array.from(this.data.subarray(k,k+traceColumns.length),x=>Number.isFinite(x)?x.toFixed(6):'').join(','));}return lines.join('\n')+'\n';}
}
